// Slackからのリクエストデータを検証・整形
const data = $json;

// Slackリクエストの基本検証
if (!data.text && !data.message) {
  return [{
    json: {
      error: true,
      message: 'テキストメッセージが見つかりません',
      statusCode: 400
    }
  }];
}

// メッセージテキストを取得
const messageText = data.text || data.message || '';
const userId = data.user_id || data.user || 'unknown';
const userName = data.user_name || 'ユーザー';
const channelId = data.channel_id || data.channel || '';

// 整形されたデータを返却
const formattedData = {
  messageText: messageText.trim(),
  userId: userId,
  userName: userName,
  channelId: channelId,
  timestamp: new Date().toISOString(),
  valid: true
};

return [{
  json: formattedData
}];

// AIエージェントの結果を解析
const agentResult = $input.first().json;
let aiResponse;

try {
  // AIの結果をパース
  if (typeof agentResult.output === 'string') {
    aiResponse = JSON.parse(agentResult.output);
  } else {
    aiResponse = agentResult.output;
  }
} catch (error) {
  // パースに失敗した場合のフォールバック
  aiResponse = {
    action: 'general_chat',
    response: 'すみません、リクエストを正しく処理できませんでした。もう一度お試しください。',
    calendar_params: {}
  };
}

// ユーザー情報を追加
const userData = $('Data Validation & Formatting').first().json;
const processedData = {
  ...aiResponse,
  userData: userData,
  processedAt: new Date().toISOString()
};

return [{
  json: processedData
}];

// カレンダー読み取り結果を整形
const calendarData = $json;
const aiData = $('AI Response Processing').first().json;

let responseMessage;

if (Array.isArray(calendarData) && calendarData.length > 0) {
  // 予定がある場合
  responseMessage = `${aiData.response}\n\n`;

  calendarData.slice(0, 5).forEach((event, index) => {
    const startTime = new Date(event.start?.dateTime || event.start?.date);
    const timeStr = startTime.toLocaleString('ja-JP', {
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
    responseMessage += `${index + 1}. **${event.summary}**\n   📅 ${timeStr}\n`;
    if (event.description) {
      responseMessage += `   📝 ${event.description.substring(0, 50)}...\n`;
    }
    responseMessage += '\n';
  });

  if (calendarData.length > 5) {
    responseMessage += `他 ${calendarData.length - 5} 件の予定があります。`;
  }
} else {
  // 予定がない場合
  responseMessage = `${aiData.response}\n\n予定されているイベントはありません。`;
}

return [{
  json: {
    text: responseMessage,
    userData: aiData.userData,
    success: true
  }
}];

// カレンダー作成結果を整形
const calendarData = $json;
const aiData = $('AI Response Processing').first().json;

let responseMessage;

if (calendarData.id) {
  // 作成成功
  const startTime = new Date(calendarData.start?.dateTime || calendarData.start?.date);
  const timeStr = startTime.toLocaleString('ja-JP', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit'
  });

  responseMessage = `✅ ${aiData.response}\n\n` +
    `**予定を作成しました！**\n` +
    `📅 **タイトル**: ${calendarData.summary}\n` +
    `🕐 **開始時刻**: ${timeStr}\n`;

  if (calendarData.description) {
    responseMessage += `📝 **説明**: ${calendarData.description}\n`;
  }

  if (calendarData.htmlLink) {
    responseMessage += `🔗 [カレンダーで確認](${calendarData.htmlLink})`;
  }
} else {
  // 作成失敗
  responseMessage = `❌ 予定の作成に失敗しました。\n\n` +
    `エラー: ${calendarData.error?.message || '不明なエラー'}\n` +
    `もう一度お試しいただくか、管理者にお問い合わせください。`;
}

return [{
  json: {
    text: responseMessage,
    userData: aiData.userData,
    success: !!calendarData.id
  }
}];

